<div class="table-wrap"><table><thead><tr><th>Pedido / EPI</th><?php if($admin): ?><th>Funcionário</th><?php endif ?><th>Quantidade</th><th>Data</th><th>Justificativa</th><th>Status</th><?php if($admin && $page!=='relatorios'): ?><th>Gerenciar</th><?php endif ?></tr></thead><tbody>
<?php foreach($requests as $r): ?><tr><td><small>#<?= (int)$r['id_solicitacao'] ?></small><strong><?= e($r['nome_epi']) ?></strong></td><?php if($admin): ?><td><?= e($r['nome_completo']) ?></td><?php endif ?><td><?= (int)$r['quantidade'] ?></td><td class="nowrap"><?= e(dateBr($r['data_solicitacao'])) ?></td><td class="long-text"><?= e($r['justificativa']) ?></td><td><?= badge($r['status_solicitacao']) ?></td><?php if($admin && $page!=='relatorios'): ?><td><?php $transitions=['Pendente'=>['Aprovada','Recusada'],'Aprovada'=>['Em andamento','Entregue','Recusada'],'Em andamento'=>['Entregue','Recusada']]; if(isset($transitions[$r['status_solicitacao']])): ?><form method="post" class="inline-form"><?= csrf() ?><input type="hidden" name="id_solicitacao" value="<?= (int)$r['id_solicitacao'] ?>"><label class="sr-only" for="status-<?= (int)$r['id_solicitacao'] ?>">Novo status do pedido <?= (int)$r['id_solicitacao'] ?></label><select id="status-<?= (int)$r['id_solicitacao'] ?>" name="status"><?php foreach($transitions[$r['status_solicitacao']] as $s): ?><option><?= e($s) ?></option><?php endforeach ?></select><button class="button small">Salvar</button></form><?php else: ?><span class="muted">Finalizada</span><?php endif ?></td><?php endif ?></tr><?php endforeach ?>
<?php if(!$requests): ?><tr><td colspan="7" class="empty">Nenhuma solicitação encontrada.</td></tr><?php endif ?></tbody></table></div>
